{
  "extracted_concepts": [
    {
      "name": "参数估计",
      "aliases": ["parameter estimation", "统计估计"],
      "definition_snippet": "利用样本信息推断总体参数的统计方法。",
      "category": "concept"
    },
    {
      "name": "点估计",
      "aliases": ["point estimation", "点估计法"],
      "definition_snippet": "用样本统计量直接给出总体参数的估计值。",
      "category": "concept"
    },
    {
      "name": "矩估计法",
      "aliases": ["method of moments estimation", "矩法估计"],
      "definition_snippet": "用样本矩替换总体矩来求参数估计的方法。",
      "category": "operation"
    },
    {
      "name": "样本矩",
      "aliases": ["sample moment", "样本矩统计量"],
      "definition_snippet": "由样本计算的矩，如 Aₖ。",
      "category": "concept"
    },
    {
      "name": "总体矩",
      "aliases": ["population moment", "母体矩"],
      "definition_snippet": "总体随机变量的矩，如 E(X^k)。",
      "category": "concept"
    },
    {
      "name": "最大似然估计法",
      "aliases": ["maximum likelihood estimation", "极大似然估计法"],
      "definition_snippet": "通过最大化似然函数求参数估计的方法。",
      "category": "operation"
    },
    {
      "name": "似然函数",
      "aliases": ["likelihood function", "似然函数 L(θ)"],
      "definition_snippet": "样本联合概率密度或概率函数关于参数的函数。",
      "category": "concept"
    },
    {
      "name": "估计量",
      "aliases": ["estimator", "估计统计量"],
      "definition_snippet": "用于估计总体参数的样本统计量。",
      "category": "concept"
    },
    {
      "name": "估计量的评价标准",
      "aliases": ["evaluation criteria of estimators", "估计量评价准则"],
      "definition_snippet": "衡量估计量好坏的标准，包括无偏性、有效性、一致性。",
      "category": "concept"
    },
    {
      "name": "无偏性",
      "aliases": ["unbiasedness", "无偏估计性"],
      "definition_snippet": "估计量的期望等于被估计参数。",
      "category": "property"
    },
    {
      "name": "样本均值",
      "aliases": ["sample mean", "样本平均数"],
      "definition_snippet": "样本观测值的平均数，记为 X̄。",
      "category": "concept"
    },
    {
      "name": "样本方差",
      "aliases": ["sample variance", "修正样本方差"],
      "definition_snippet": "样本离差平方和除以 n-1，记为 S²。",
      "category": "concept"
    },
    {
      "name": "有效性",
      "aliases": ["efficiency", "估计有效性"],
      "definition_snippet": "方差较小的估计量更有效。",
      "category": "property"
    },
    {
      "name": "方差",
      "aliases": ["variance", "离散程度"],
      "definition_snippet": "随机变量或估计量取值离散程度的度量。",
      "category": "concept"
    },
    {
      "name": "一致性",
      "aliases": ["consistency", "相合性"],
      "definition_snippet": "样本量趋于无穷时估计量依概率收敛到参数真值。",
      "category": "property"
    },
    {
      "name": "区间估计",
      "aliases": ["interval estimation", "区间估计法"],
      "definition_snippet": "给出总体参数可能取值区间及置信水平的估计方法。",
      "category": "concept"
    },
    {
      "name": "置信区间",
      "aliases": ["confidence interval", "置信区间估计"],
      "definition_snippet": "以一定概率覆盖总体参数的随机区间。",
      "category": "concept"
    },
    {
      "name": "置信水平",
      "aliases": ["confidence level", "置信系数"],
      "definition_snippet": "置信区间覆盖参数的概率，记为 1-α。",
      "category": "concept"
    },
    {
      "name": "正态总体均值的区间估计",
      "aliases": ["interval estimation of normal mean", "正态均值区间估计"],
      "definition_snippet": "根据方差已知或未知构造正态总体均值的置信区间。",
      "category": "operation"
    },
    {
      "name": "正态总体方差的区间估计",
      "aliases": ["interval estimation of normal variance", "正态方差区间估计"],
      "definition_snippet": "利用卡方分布构造正态总体方差的置信区间。",
      "category": "operation"
    },
    {
      "name": "抽样分布",
      "aliases": ["sampling distribution", "样本统计量分布"],
