      "category": "concept"
    },
    {
      "name": "统计量",
      "aliases": ["statistic", "样本函数"],
      "definition_snippet": "样本的函数，不含未知参数。",
      "category": "concept"
    },
    {
      "name": "总体均值",
      "aliases": ["population mean", "总体期望"],
      "definition_snippet": "正态总体的均值参数 μ。",
      "category": "concept"
    },
    {
      "name": "总体方差",
      "aliases": ["population variance", "母体方差"],
      "definition_snippet": "正态总体的方差参数 σ²。",
      "category": "concept"
    },
    {
      "name": "标准正态分布",
      "aliases": ["standard normal distribution", "z分布"],
      "definition_snippet": "用于构造 σ² 已知时均值置信区间的分布。",
      "category": "concept"
    },
    {
      "name": "t分布",
      "aliases": ["t distribution", "学生t分布"],
      "definition_snippet": "用于 σ² 未知时均值置信区间的分布。",
      "category": "concept"
    },
    {
      "name": "卡方分布",
      "aliases": ["chi-square distribution", "χ²分布"],
      "definition_snippet": "用于正态总体方差区间估计的分布。",
      "category": "concept"
    }
  ],
